/**
 * API response types
 */

export interface ApiResponse<T = any> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
  requestId?: string;
}

// ============================================================================
// ERROR RESPONSE TYPES
// ============================================================================

/**
 * Service unavailability error details
 * Matches the error response structure from the API when service is unavailable
 * Example:
 * {
 *   "error": 503,
 *   "code": "SERVICE_UNAVAILABLE",
 *   "message": "Service temporarily unavailable",
 *   "details": {
 *     "service_status": "UNAVAILABLE",
 *     "reads_allowed": false,
 *     "writes_allowed": false,
 *     "streams_allowed": false,
 *     "circuit_breaker_state": "OPEN",
 *     "retry_after_seconds": 30,
 *     "request_type": "read"
 *   },
 *   "timestamp": 1769317535
 * }
 */
/** 503 details (camelCase). Normalize wire snake_case before typing. */
export interface ServiceUnavailableErrorDetails {
  serviceStatus?: "UNAVAILABLE" | "DEGRADED" | "AVAILABLE";
  readsAllowed?: boolean;
  writesAllowed?: boolean;
  streamsAllowed?: boolean;
  circuitBreakerState?: "OPEN" | "CLOSED" | "HALF_OPEN";
  retryAfterSeconds?: number;
  requestType?: "read" | "write" | "stream" | string;
  service?: string;
  reason?: string;
  [key: string]: any;
}

/**
 * Service unavailability error response
 * HTTP 503 error response structure from the API
 */
export interface ServiceUnavailableError {
  error: number; // HTTP status code (e.g., 503)
  code: string; // Error code (e.g., "SERVICE_UNAVAILABLE")
  message: string; // Human-readable error message
  details: ServiceUnavailableErrorDetails;
  timestamp: number; // Unix timestamp
  [key: string]: any; // Allow additional fields
}

/**
 * Generic API error response structure
 * Can represent various error types from the API
 */
export interface ApiErrorResponse {
  error?: number | string; // HTTP status code or error identifier
  code?: string; // Error code
  message?: string; // Human-readable error message
  details?: Record<string, any>; // Additional error details
  timestamp?: number; // Unix timestamp
  [key: string]: any; // Allow additional fields
}

export type SubscriptionCallback = (data: any) => void;

