// ============================================================================
// CONSENSUS FLAT TYPES
// ============================================================================

/**
 * Consensus item type union
 */
export type ConsensusItemType =
  | "vertex"
  | "tx"
  | "validator"
  | "unconfirmed_tx";

/**
 * Consensus event type union
 */
export type ConsensusEventType =
  | "new_vertex"
  | "new_tx"
  | "validator_update"
  | string;

/**
 * Common fields for all consensus item types (ConsensusCommonItemFlat)
 * These fields are present in all consensus items regardless of type.
 */
export interface ConsensusCommonItemFlat {
  id: string;
  type: ConsensusItemType;
  shardId: number;
  timestamp: number;
  status: string;
  originalProtoHash: string;
}

/**
 * Vertex-specific consensus item (ConsensusVertexItemFlat)
 * Represents a DAG vertex/block in the consensus system.
 */
export interface ConsensusVertexItemFlat extends ConsensusCommonItemFlat {
  type: "vertex";
  parentIds?: string[];
  txCount?: number;
  stateRoot?: string;
  qcAchieved?: boolean;
  qcVoteCount?: number;
  qcAggSignature?: string;
}

/**
 * Transaction-specific consensus item (ConsensusTxItemFlat)
 * Represents a confirmed transaction in the consensus system.
 */
export interface ConsensusTxItemFlat extends ConsensusCommonItemFlat {
  type: "tx";
  fromAddress?: string;
  toAddress?: string;
  amount?: string;
  txType?: string;
  txHash?: string;
  nonce?: number;
}

/**
 * Unconfirmed transaction-specific consensus item (ConsensusUnconfirmedTxItemFlat)
 * Represents an unconfirmed transaction in the consensus system.
 */
export interface ConsensusUnconfirmedTxItemFlat
  extends ConsensusCommonItemFlat {
  type: "unconfirmed_tx";
  fromAddress?: string;
  toAddress?: string;
  amount?: string;
  txType?: string;
  txHash?: string;
  nonce?: number;
}

/**
 * Validator-specific consensus item (ConsensusValidatorItemFlat)
 * Represents a validator in the consensus system.
 */
export interface ConsensusValidatorItemFlat extends ConsensusCommonItemFlat {
  type: "validator";
  votingPower?: number;
  publicKey?: string;
  validatorStatus?: string;
  validatorId?: string;
}

/**
 * Union type for all consensus item types (ConsensusItemFlat)
 * This is a discriminated union based on the `type` field, allowing TypeScript
 * to narrow the type based on the `type` property.
 */
export type ConsensusItemFlat =
  | ConsensusVertexItemFlat
  | ConsensusTxItemFlat
  | ConsensusUnconfirmedTxItemFlat
  | ConsensusValidatorItemFlat;

/**
 * Consensus event flat structure (ConsensusEventFlat)
 * Flattened (linearized) consensus events from Morpheum's DAG-based consensus system.
 * This is designed for easier consumption by block explorers and clients, converting
 * complex DAG structures into a simpler, block-like event stream.
 *
 * The payload follows the `ConsensusEventFlat` Go struct (from `services/consensus/types.go`),
 * which is marshaled to JSON using `protojson` (snake_case fields, no zero values emitted).
 */
export interface ConsensusEventFlat {
  eventType: ConsensusEventType;
  data: ConsensusItemFlat;
  sourceShard: string;
  eventTime: number;
}

