/**
 * Discriminated union type for multi-feed sub-channel data
 * Each sub-channel has its own specific data structure
 */
export type MultiFeedSubChannelData =
  | { subChannel: "orderbook"; data: MultiFeedOrderbookData }
  | { subChannel: "trades"; data: MultiFeedTradesData }
  | { subChannel: "positions"; data: MultiFeedPositionsData }
  | { subChannel: "orders"; data: MultiFeedOrdersData }
  | { subChannel: "buckets"; data: MultiFeedBucketsData }
  | { subChannel: "balances"; data: MultiFeedBalancesData }
  | { subChannel: "mark_price"; data: MultiFeedMarkPriceData }
  | { subChannel: "funding_rate"; data: MultiFeedFundingRateData }
  | { subChannel: "deviation"; data: MultiFeedDeviationData }
  | { subChannel: "twap"; data: MultiFeedTWAPData }
  | { subChannel: "kline"; data: MultiFeedKlineData }
  | { subChannel: "last_price"; data: MultiFeedLastPriceData }
  | { subChannel: "index_price"; data: MultiFeedIndexPriceData }
  | { subChannel: "price_feed"; data: MultiFeedPriceFeedData }
  | { subChannel: string; data: any };

/**
 * Multi-feed message structure (complete message with envelope).
 * Use subChannel ?? sub_channel for channel name (both wire formats supported).
 */
export interface MultiFeedMessage extends MultiFeedRawEnvelope {
  data: any;
}

/**
 * Type guard to check if a message is a multi-feed orderbook message (proto camelCase).
 */
export function isMultiFeedOrderbook(
  message: MultiFeedMessage,
): message is MultiFeedRawEnvelope & {
  subChannel: "orderbook";
  data: MultiFeedOrderbookData;
} {
  return (message as MultiFeedRawEnvelope).subChannel === "orderbook";
}

