// ============================================================================
// UNIFIED MULTIPLEX STREAM API (channel "multiplex" + action/subscriptions)
// Mirrors orchestrator e2e_tests/stream and router/websocket/multiplex/types.go
// ============================================================================

/** Stream type identifiers for the multiplex API (same as E2E and router). */
export type MultiplexStreamType =
  | "price_feed"
  | "volatility"
  | "index_price"
  | "markPrice"
  | "funding_rate"
  | "deviation"
  | "orderbook"
  | "trades"
  | "positions"
  | "transactions";

/** Action for multiplex requests. */
export type MultiplexAction = "subscribe" | "unsubscribe" | "ping";

/** Stream filter (wire format). Only relevant fields per stream_type are used. */
export interface MultiplexStreamFilter {
  symbols?: string[];
  market_indices?: number[];
  include_all?: boolean;
  update_interval_ms?: number;
  include_snapshot?: boolean;
  sources?: string[];
  include_aggregated?: boolean;
  depth?: number;
  address?: string;
  tx_types?: string[];
  shardId?: string;
}

/** Single stream subscription in a multiplex request. */
export interface MultiplexStreamSubscription {
  stream_type: MultiplexStreamType;
  filter?: MultiplexStreamFilter;
}

/** Client → server: subscribe/unsubscribe streams or ping. */
export interface MultiplexRequest {
  action: MultiplexAction;
  id?: string;
  subscriptions?: MultiplexStreamSubscription[];
}

/** Server → client: ack, data, error, pong. */
export interface MultiplexResponse {
  type: "ack" | "data" | "error" | "pong";
  id?: string;
  stream_type?: MultiplexStreamType;
  symbol?: string;
  marketIndex?: number;
  data?: unknown;
  error?: MultiplexErrorDetail;
  U?: number;
  u?: number;
  ts?: number;
}

export interface MultiplexErrorDetail {
  code: string;
  message: string;
  details?: string;
}

/** Callback for multiplex stream data (one per stream_type). */
export type MultiplexDataCallback = (resp: MultiplexResponse) => void;
