    const callback = (message: MultiFeedMessage) => {
      const subChannel = message.subChannel ?? "unknown";

      if (isMultiFeedOrderbook(message)) {
        console.debug("Orderbook update:", message.data.bids.length, "bids");
      } else if (isMultiFeedTrades(message)) {
        console.debug("Trade:", message.data.tradeId, message.data.price);
      } else if (isMultiFeedPositions(message)) {
        console.debug("Position update:", message.data.symbol, message.data.size);
      } else if (isMultiFeedOrders(message)) {
        console.debug("Order update:", message.data.orderId, message.data.status);
      } else if (isMultiFeedBuckets(message)) {
        console.debug("Buckets update:", message.data.totalBuckets);
      } else if (isMultiFeedBalances(message)) {
        // message.data is now typed as MultiFeedBalancesData
        console.debug("Balances update:", message.data.count, "assets");
      }
      
      // Add message to UI (message includes envelope + data)
      addMessage(
        `multi_feed:${subChannel}`,
        message,
        "success",
        subChannel === "balances" ||
          subChannel === "buckets" ||
          subChannel === "orders" ||
          subChannel === "positions",
      );
    };

